    def permuteUnique(self, nums):
        if len(nums) == 1:
            return [[nums[0]]]

        res = self.permuteUnique(nums[1:])

        for i in range(len(res)-1, -1 , -1):
            j = 0
            while j < len(res[i]):
                if res[i][j] == nums[0]: #to account for repeated nums
                    break
                lst = res[i][:]
                lst.insert(j, nums[0])
                res.append(lst)
                j += 1

            res[i].insert(j,nums[0])

        return res

class Solution:
    def permuteUnique(self, nums):
        solutions = [[]]

        for num in nums:
            next = []
            for solution in solutions:
                for i in range(len(solution) + 1):
                    candidate = solution[:i] + [num] + solution[i:]
                    if candidate not in next:
                        next.append(candidate)

            solutions = next

        return solutions

